cat > /tmp/probe/scratch/mpred.awk <<'EOF'
function pred(w,  n,last,l2,l3) {
  n=length(w); last=substr(w,n,1); l2=substr(w,n-1,2); l3=substr(w,n-2,3);
  if (n>=2 && l2=="es") return w;
  if (n>=2 && last=="y" && substr(w,n-1,1) !~ /[aeiou]/) return substr(w,1,n-1) "ies";
  if (last=="s" || l2=="ch" || l2=="sh") return w "es";
  return w "s";
}
BEGIN{FS="\t"; OFS="\t"}
{ p=pred($1); if (p != $2) print $1, $2, p }
EOF
awk -f /tmp/probe/scratch/mpred.awk /tmp/probe/data/common-nouns-m.tsv | wc -l
awk -f /tmp/probe/scratch/mpred.awk /tmp/probe/data/common-nouns-m.tsv | head -100
